package com.example.ancapp.data

import android.content.Context
import com.example.ancapp.fhir.AppSyncWorker
import com.ionspin.kotlin.bignum.decimal.BigDecimal
import dev.ohs.fhir.engine.FhirEngine
import dev.ohs.fhir.engine.FhirEngineProvider
import dev.ohs.fhir.engine.get
import dev.ohs.fhir.engine.search.ReferenceClientParam
import dev.ohs.fhir.engine.search.Search
import dev.ohs.fhir.engine.sync.CurrentSyncJobStatus
import dev.ohs.fhir.engine.sync.Sync
import dev.ohs.fhir.model.r4.Canonical
import dev.ohs.fhir.model.r4.Code
import dev.ohs.fhir.model.r4.CodeableConcept
import dev.ohs.fhir.model.r4.Coding
import dev.ohs.fhir.model.r4.DateTime
import dev.ohs.fhir.model.r4.Decimal
import dev.ohs.fhir.model.r4.Encounter
import dev.ohs.fhir.model.r4.Enumeration
import dev.ohs.fhir.model.r4.FhirDateTime
import dev.ohs.fhir.model.r4.Observation
import dev.ohs.fhir.model.r4.Patient
import dev.ohs.fhir.model.r4.Period
import dev.ohs.fhir.model.r4.Quantity
import dev.ohs.fhir.model.r4.Questionnaire
import dev.ohs.fhir.model.r4.QuestionnaireResponse
import dev.ohs.fhir.model.r4.Reference
import dev.ohs.fhir.model.r4.Uri
import dev.ohs.fhir.model.r4.String as FhirString
import dev.ohs.fhir.model.r4.terminologies.ResourceType
import java.time.LocalDate
import java.time.OffsetDateTime
import java.time.format.DateTimeFormatter
import java.time.temporal.ChronoUnit
import java.util.UUID
import kotlinx.coroutines.flow.first
import kotlinx.coroutines.withTimeoutOrNull
import kotlinx.serialization.json.Json

object Loinc {
  const val SYSTEM = "http://loinc.org"
  const val EDD = "11778-8"
  const val WEIGHT = "29463-7"
  const val BP_PANEL = "85354-9"
  const val BP_SYSTOLIC = "8480-6"
  const val BP_DIASTOLIC = "8462-4"
  const val HEMOGLOBIN = "718-7"
  const val GESTATIONAL_AGE = "11884-4"
  const val NOTES = "48767-8"
}

const val DANGER_SIGN_SYSTEM = "urn:example:anc-danger-signs"
const val UCUM_SYSTEM = "http://unitsofmeasure.org"
const val QUESTIONNAIRE_ID = "anc-contact"

data class PatientRow(
  val id: String,
  val name: String,
  val ageYears: Long?,
  val dueDate: LocalDate?,
  val gestationalWeeks: Long?,
)

data class VisitRow(
  val encounterId: String,
  val date: LocalDate?,
  val gestationalWeeks: String?,
  val weightKg: String?,
  val systolic: String?,
  val diastolic: String?,
  val hemoglobin: String?,
  val dangerSigns: List<String>,
  val notes: String?,
)

object AncRepository {

  private val json = Json {
    explicitNulls = false
    encodeDefaults = false
  }

  private fun engine(context: Context): FhirEngine =
    FhirEngineProvider.getInstance(context.applicationContext)

  /** Runs a one-time upload+download sync; returns true when it succeeded. */
  suspend fun sync(context: Context): Boolean {
    val terminal =
      withTimeoutOrNull(120_000) {
        Sync.oneTimeSync<AppSyncWorker>(context.applicationContext).first {
          it is CurrentSyncJobStatus.Succeeded ||
            it is CurrentSyncJobStatus.Failed ||
            it is CurrentSyncJobStatus.Cancelled
        }
      }
    return terminal is CurrentSyncJobStatus.Succeeded
  }

  suspend fun loadRegister(context: Context): List<PatientRow> {
    val engine = engine(context)
    val patients =
      engine.search<Patient>(Search(ResourceType.Patient)).map { it.resource }
    val eddByPatient =
      engine
        .search<Observation>(Search(ResourceType.Observation))
        .map { it.resource }
        .filter { obs -> obs.code.coding.any { it.code?.value == Loinc.EDD } }
        .groupBy { it.subject?.reference?.value?.substringAfter("Patient/") }

    val today = LocalDate.now()
    return patients
      .map { patient ->
        val edd =
          eddByPatient[patient.id]
            ?.mapNotNull { obs -> obs.value?.asDateTime()?.value?.value?.toString()?.toLocalDate() }
            ?.maxOrNull()
        val gaWeeks =
          edd?.let { (280 - ChronoUnit.DAYS.between(today, it)) / 7 }?.takeIf { it in 0..45 }
        PatientRow(
          id = patient.id.orEmpty(),
          name = patient.humanName(),
          ageYears = patient.birthDate?.value?.toString()?.toLocalDate()?.let {
            ChronoUnit.YEARS.between(it, today)
          },
          dueDate = edd,
          gestationalWeeks = gaWeeks,
        )
      }
      .sortedWith(compareBy(nullsLast()) { it.dueDate })
  }

  suspend fun getPatientName(context: Context, patientId: String): String =
    runCatching { engine(context).get<Patient>(patientId).humanName() }.getOrDefault(patientId)

  suspend fun loadVisits(context: Context, patientId: String): List<VisitRow> {
    val engine = engine(context)
    val encounters =
      engine
        .search<Encounter>(
          Search(ResourceType.Encounter).apply {
            filter(ReferenceClientParam("subject"), { value = "Patient/$patientId" })
          }
        )
        .map { it.resource }
    val obsByEncounter =
      engine
        .search<Observation>(
          Search(ResourceType.Observation).apply {
            filter(ReferenceClientParam("subject"), { value = "Patient/$patientId" })
          }
        )
        .map { it.resource }
        .groupBy { it.encounter?.reference?.value?.substringAfter("Encounter/") }

    return encounters
      .map { encounter ->
        val obs = obsByEncounter[encounter.id].orEmpty()
        val bp = obs.firstWithCode(Loinc.BP_PANEL)
        VisitRow(
          encounterId = encounter.id.orEmpty(),
          date = encounter.period?.start?.value?.toString()?.toLocalDate(),
          gestationalWeeks = obs.firstWithCode(Loinc.GESTATIONAL_AGE)?.quantityValue(),
          weightKg = obs.firstWithCode(Loinc.WEIGHT)?.quantityValue(),
          systolic = bp?.componentValue(Loinc.BP_SYSTOLIC),
          diastolic = bp?.componentValue(Loinc.BP_DIASTOLIC),
          hemoglobin = obs.firstWithCode(Loinc.HEMOGLOBIN)?.quantityValue(),
          dangerSigns =
            obs
              .filter { o ->
                o.value?.asCodeableConcept()?.coding?.any { it.system?.value == DANGER_SIGN_SYSTEM } == true
              }
              .flatMap { o ->
                o.value?.asCodeableConcept()?.coding.orEmpty().mapNotNull {
                  it.display?.value ?: it.code?.value
                }
              },
          notes = obs.firstWithCode(Loinc.NOTES)?.value?.asString()?.value,
        )
      }
      .sortedWith(compareByDescending(nullsLast<LocalDate>()) { it.date })
  }

  suspend fun getQuestionnaireJson(context: Context): String {
    val questionnaire = engine(context).get<Questionnaire>(QUESTIONNAIRE_ID)
    return json.encodeToString(questionnaire)
  }

  /**
   * Maps the submitted QuestionnaireResponse to an Encounter plus Observations, saves them
   * (and the response itself) locally, then kicks off a sync to the server.
   */
  suspend fun saveVisit(context: Context, patientId: String, response: QuestionnaireResponse) {
    val answers = mutableMapOf<String, MutableList<QuestionnaireResponse.Item.Answer>>()
    fun collect(items: List<QuestionnaireResponse.Item>) {
      items.forEach { item ->
        item.linkId.value?.let { linkId ->
          answers.getOrPut(linkId) { mutableListOf() }.addAll(item.answer)
        }
        collect(item.item)
        item.answer.forEach { collect(it.item) }
      }
    }
    collect(response.item)

    val visitDate =
      answers["visit-date"]?.firstOrNull()?.value?.asDate()?.value?.value?.toString()
        ?: LocalDate.now().toString()
    val gestationalAge = answers["gestational-age"]?.firstOrNull()?.value?.asInteger()?.value?.value
    val weight = answers["weight"]?.firstOrNull()?.value?.asDecimal()?.value?.value
    val systolic = answers["bp-systolic"]?.firstOrNull()?.value?.asInteger()?.value?.value
    val diastolic = answers["bp-diastolic"]?.firstOrNull()?.value?.asInteger()?.value?.value
    val dangerSigns =
      answers["danger-signs"].orEmpty().mapNotNull { it.value?.asCoding() }.filter {
        it.code?.value != "none"
      }
    val notes = answers["notes"]?.firstOrNull()?.value?.asString()?.value?.takeIf { it.isNotBlank() }

    val encounterId = UUID.randomUUID().toString()
    val patientRef = Reference(reference = FhirString(value = "Patient/$patientId"))
    val encounterRef = Reference(reference = FhirString(value = "Encounter/$encounterId"))
    val visitDateTime = DateTime(value = FhirDateTime.fromString(visitDate))
    val effective = Observation.Effective.DateTime(visitDateTime)

    val vitalSignsCategory =
      CodeableConcept(
        coding =
          listOf(
            Coding(
              system = Uri(value = "http://terminology.hl7.org/CodeSystem/observation-category"),
              code = Code(value = "vital-signs"),
              display = FhirString(value = "Vital Signs"),
            )
          )
      )

    fun loincConcept(code: String, display: String) =
      CodeableConcept(
        coding =
          listOf(
            Coding(
              system = Uri(value = Loinc.SYSTEM),
              code = Code(value = code),
              display = FhirString(value = display),
            )
          ),
        text = FhirString(value = display),
      )

    fun quantity(value: BigDecimal, unit: String, ucumCode: String) =
      Quantity(
        value = Decimal(value = value),
        unit = FhirString(value = unit),
        system = Uri(value = UCUM_SYSTEM),
        code = Code(value = ucumCode),
      )

    fun observation(
      code: CodeableConcept,
      value: Observation.Value? = null,
      component: List<Observation.Component> = emptyList(),
      category: List<CodeableConcept> = emptyList(),
    ) =
      Observation(
        id = UUID.randomUUID().toString(),
        status = Enumeration(value = Observation.ObservationStatus.Final),
        category = category,
        code = code,
        subject = patientRef,
        encounter = encounterRef,
        effective = effective,
        value = value,
        component = component,
      )

    val observations = buildList {
      gestationalAge?.let {
        add(
          observation(
            code = loincConcept(Loinc.GESTATIONAL_AGE, "Gestational age"),
            value =
              Observation.Value.Quantity(quantity(BigDecimal.fromInt(it), "weeks", "wk")),
          )
        )
      }
      weight?.let {
        add(
          observation(
            code = loincConcept(Loinc.WEIGHT, "Body weight"),
            value = Observation.Value.Quantity(quantity(it, "kg", "kg")),
            category = listOf(vitalSignsCategory),
          )
        )
      }
      if (systolic != null || diastolic != null) {
        add(
          observation(
            code = loincConcept(Loinc.BP_PANEL, "Blood pressure"),
            category = listOf(vitalSignsCategory),
            component =
              buildList {
                systolic?.let {
                  add(
                    Observation.Component(
                      code = loincConcept(Loinc.BP_SYSTOLIC, "Systolic blood pressure"),
                      value =
                        Observation.Component.Value.Quantity(
                          quantity(BigDecimal.fromInt(it), "mmHg", "mm[Hg]")
                        ),
                    )
                  )
                }
                diastolic?.let {
                  add(
                    Observation.Component(
                      code = loincConcept(Loinc.BP_DIASTOLIC, "Diastolic blood pressure"),
                      value =
                        Observation.Component.Value.Quantity(
                          quantity(BigDecimal.fromInt(it), "mmHg", "mm[Hg]")
                        ),
                    )
                  )
                }
              },
          )
        )
      }
      dangerSigns.forEach { sign ->
        add(
          observation(
            code = CodeableConcept(text = FhirString(value = "Danger sign present")),
            value = Observation.Value.CodeableConcept(CodeableConcept(coding = listOf(sign))),
          )
        )
      }
      notes?.let {
        add(
          observation(
            code = loincConcept(Loinc.NOTES, "Visit notes"),
            value = Observation.Value.String(FhirString(value = it)),
          )
        )
      }
    }

    val encounter =
      Encounter(
        id = encounterId,
        status = Enumeration(value = Encounter.EncounterStatus.Finished),
        `class` =
          Coding(
            system = Uri(value = "http://terminology.hl7.org/CodeSystem/v3-ActCode"),
            code = Code(value = "AMB"),
            display = FhirString(value = "ambulatory"),
          ),
        type = listOf(CodeableConcept(text = FhirString(value = "Antenatal care contact"))),
        subject = patientRef,
        period = Period(start = visitDateTime, end = visitDateTime),
      )

    val savedResponse =
      response
        .toBuilder()
        .apply {
          id = UUID.randomUUID().toString()
          questionnaire =
            Canonical(value = "http://example.org/fhir/Questionnaire/$QUESTIONNAIRE_ID").toBuilder()
          status = Enumeration(value = QuestionnaireResponse.QuestionnaireResponseStatus.Completed)
          subject = patientRef.toBuilder()
          encounter = encounterRef.toBuilder()
          authored =
            DateTime(
                value =
                  FhirDateTime.fromString(
                    OffsetDateTime.now()
                      .format(DateTimeFormatter.ofPattern("yyyy-MM-dd'T'HH:mm:ssXXX"))
                  )
              )
              .toBuilder()
        }
        .build()

    engine(context).create(encounter, *observations.toTypedArray(), savedResponse)
  }
}

private fun Patient.humanName(): String {
  val name = name.firstOrNull() ?: return id.orEmpty()
  val given = name.given.mapNotNull { it.value }.joinToString(" ")
  val family = name.family?.value.orEmpty()
  return listOf(given, family).filter { it.isNotBlank() }.joinToString(" ").ifBlank { id.orEmpty() }
}

private fun List<Observation>.firstWithCode(code: String): Observation? =
  firstOrNull { obs -> obs.code.coding.any { it.code?.value == code } }

private fun Observation.quantityValue(): String? =
  value?.asQuantity()?.value?.value?.toPlainString()

private fun Observation.componentValue(code: String): String? =
  component
    .firstOrNull { comp -> comp.code.coding.any { it.code?.value == code } }
    ?.value
    ?.asQuantity()
    ?.value
    ?.value
    ?.toPlainString()

private fun String.toLocalDate(): LocalDate? =
  runCatching { LocalDate.parse(take(10)) }.getOrNull()

