package com.example.ancapp

import android.os.Bundle
import androidx.activity.ComponentActivity
import androidx.activity.compose.BackHandler
import androidx.activity.compose.setContent
import androidx.compose.material3.MaterialTheme
import androidx.compose.material3.Surface
import androidx.compose.runtime.Composable
import androidx.compose.runtime.LaunchedEffect
import androidx.compose.runtime.getValue
import androidx.compose.runtime.mutableIntStateOf
import androidx.compose.runtime.mutableStateOf
import androidx.compose.runtime.remember
import androidx.compose.runtime.setValue
import androidx.compose.ui.platform.LocalContext
import com.example.ancapp.data.AncRepository
import com.example.ancapp.ui.PatientDetailScreen
import com.example.ancapp.ui.RegisterScreen
import com.example.ancapp.ui.SyncUiState
import com.example.ancapp.ui.VisitFormScreen

class MainActivity : ComponentActivity() {
  override fun onCreate(savedInstanceState: Bundle?) {
    super.onCreate(savedInstanceState)
    setContent { MaterialTheme { Surface { AncApp() } } }
  }
}

sealed interface Screen {
  data object Register : Screen

  data class PatientDetail(val patientId: String) : Screen

  data class VisitForm(val patientId: String) : Screen
}

@Composable
fun AncApp() {
  val context = LocalContext.current
  var screen by remember { mutableStateOf<Screen>(Screen.Register) }
  var syncState by remember { mutableStateOf(SyncUiState.SYNCING) }
  var refreshKey by remember { mutableIntStateOf(0) }

  // Initial sync with the HAPI server; the local engine database is the offline cache.
  LaunchedEffect(Unit) {
    syncState = if (AncRepository.sync(context)) SyncUiState.SYNCED else SyncUiState.OFFLINE
    refreshKey++
  }

  BackHandler(enabled = screen != Screen.Register) {
    screen =
      when (val current = screen) {
        is Screen.VisitForm -> Screen.PatientDetail(current.patientId)
        else -> Screen.Register
      }
  }

  when (val current = screen) {
    is Screen.Register ->
      RegisterScreen(
        refreshKey = refreshKey,
        syncState = syncState,
        onPatientClick = { screen = Screen.PatientDetail(it) },
      )
    is Screen.PatientDetail ->
      PatientDetailScreen(
        patientId = current.patientId,
        refreshKey = refreshKey,
        onBack = { screen = Screen.Register },
        onRecordVisit = { screen = Screen.VisitForm(current.patientId) },
      )
    is Screen.VisitForm ->
      VisitFormScreen(
        patientId = current.patientId,
        onSaved = {
          refreshKey++
          screen = Screen.PatientDetail(current.patientId)
        },
        onCancel = { screen = Screen.PatientDetail(current.patientId) },
      )
  }
}

