import androidx.compose.runtime.mutableStateOf
import androidx.compose.runtime.produceState
import androidx.compose.runtime.remember
import androidx.compose.runtime.rememberCoroutineScope
import androidx.compose.runtime.setValue
import androidx.compose.ui.Alignment
import androidx.compose.ui.Modifier
import androidx.compose.ui.platform.LocalContext
import androidx.compose.ui.unit.sp
import com.example.ancapp.data.AncRepository
import dev.ohs.fhir.datacapture.Questionnaire
import kotlin.coroutines.cancellation.CancellationException
import kotlinx.coroutines.launch

@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun VisitFormScreen(patientId: String, onSaved: () -> Unit, onCancel: () -> Unit) {
  val context = LocalContext.current
  val scope = rememberCoroutineScope()
  var saving by remember { mutableStateOf(false) }
  var error by remember { mutableStateOf<String?>(null) }

  val questionnaireJson by
    produceState<String?>(initialValue = null) {
      value =
        runCatching { AncRepository.getQuestionnaireJson(context) }
          .onFailure { error = "Could not load the visit form. Sync with the server first." }
          .getOrNull()
    }

  Scaffold(
    topBar = {
      TopAppBar(
        title = { Text("New ANC Visit") },
        navigationIcon = { IconButton(onClick = onCancel) { Text("←", fontSize = 22.sp) } },
      )
    }
  ) { padding ->
    Box(Modifier.padding(padding).fillMaxSize()) {
      val json = questionnaireJson
      when {
        error != null ->
          Box(Modifier.fillMaxSize(), contentAlignment = Alignment.Center) {
            Text(
              error.orEmpty(),
              style = MaterialTheme.typography.bodyLarge,
              color = MaterialTheme.colorScheme.error,
            )
          }
        json == null || saving ->
          Box(Modifier.fillMaxSize(), contentAlignment = Alignment.Center) {
            CircularProgressIndicator()
          }
        else ->
          Questionnaire(
            questionnaireJson = json,
            onSubmit = { getResponse ->
              scope.launch {
                try {
                  val response = getResponse()
                  saving = true
                  AncRepository.saveVisit(context, patientId, response)
                  onSaved()
                } catch (e: CancellationException) {
                  // Validation failed; the form shows the errors itself.
                } catch (e: Exception) {
                  saving = false
                  error = "Could not save the visit: ${e.message}"
                }
              }
            },
            onCancel = onCancel,
          )
      }
    }
  }
}

