// Individual PUT-as-create requests: HAPI's validator rejects the engine's transaction
// bundles (relative fullUrl), and client-assigned UUIDs keep references stable.
override fun getUploadStrategy(): UploadStrategy =
  UploadStrategy.forIndividualRequest(
    methodForCreate = HttpCreateMethod.PUT,
    methodForUpdate = HttpUpdateMethod.PATCH,
    squash = true,
  )

